theorem Submodule.extracted_1.{u_3, u_2, u_1} {B : Type u_1} {F : Type u_2} {R : Type u_3} [inst : DivisionRing R]
  [inst_1 : AddCommGroup B] [inst_2 : AddCommGroup F] [inst_3 : Module R B] [inst_4 : Module R F]
  (E : Submodule R (B × F)) :
  let π₁ := LinearMap.fst R B F;
  let f₁ := π₁.submoduleMap E;
  range (π₁.submoduleMap E) = ⊤ →
    ∀ (φ : B →ₗ[R] ↥E),
      f₁ ∘ₗ φ ∘ₗ (map π₁ E).subtype = LinearMap.id →
        let φ' := φ ∘ₗ (map π₁ E).subtype;
        let p₂ := (LinearMap.snd R B F).domRestrict E;
        let f₂'' := LinearMap.id - φ' ∘ₗ f₁;
        let f₂' := p₂ ∘ₗ f₂'';
        let f₂ := f₂'.rangeRestrict;
        IsCompl (ker f₁) (ker f₂) := sorry

theorem Submodule.extracted_1.{u_3, u_2, u_1} {B : Type u_1} {F : Type u_2} {R : Type u_3} [inst : DivisionRing R]
  [inst_1 : AddCommGroup B] [inst_2 : AddCommGroup F] [inst_3 : Module R B] [inst_4 : Module R F]
  (E : Submodule R (B × F)) :
  let π₁ := LinearMap.fst R B F;
  let f₁ := π₁.submoduleMap E;
  range (π₁.submoduleMap E) = ⊤ →
    ∀ (φ : B →ₗ[R] ↥E),
      f₁ ∘ₗ φ ∘ₗ (map π₁ E).subtype = LinearMap.id →
        let φ' := φ ∘ₗ (map π₁ E).subtype;
        let p₂ := (LinearMap.snd R B F).domRestrict E;
        let f₂'' := LinearMap.id - φ' ∘ₗ f₁;
        let f₂' := p₂ ∘ₗ f₂'';
        let f₂ := f₂'.rangeRestrict;
        IsCompl (ker f₁) (ker f₂) →
          ∃ B' F' f φ,
            (∀ (x : ↥E), ↑(f x).1 = (↑x).1 ∧ ↑(f x).2 = (↑x).2 - φ (↑x).1) ∧
              ∀ (x₁ : ↥B') (x₂ : ↥F'), ↑(f.symm (x₁, x₂)) = (↑x₁, ↑x₂ + φ ↑x₁) := sorry
